func isValid(_ s: String) -> Bool {
    let pairs: [Character: Character] = [")": "(", "]": "[", "}": "{"]
    var stack: [Character] = []
    for c in s {
        if let open = pairs[c] {
            guard stack.popLast() == open else { return false }
        } else {
            stack.append(c)
        }
    }
    return stack.isEmpty
}
